.config/nacre/desktop-niri.kdl.text:
animations {  }
layout {
    gaps 6
    border { width 3; }
    focus-ring { width 3; }
}
window-rule {
    exclude app-id="^org[.]quickshell$" title="^Nacre Pearl "
    geometry-corner-radius 10
    clip-to-geometry true
}
layer-rule {
    match namespace="^nacre-(topbar|lock-preview|left-menu-handle|right-menu-handle)$"
    background-effect { blur true; }
}
window-rule {
    shadow { on; }
    background-effect { blur true; }
}
input {
    focus-follows-mouse max-scroll-amount="0%"
    touchpad { natural-scroll; scroll-factor 0.25; }
}
output "DP-1" {
    mode "2560x1440@120.000"
    scale 1.25
    position x=0 y=0
    transform "normal"
}
output "DP-2" {
    mode "1920x1080@120.000"
    scale 1
    position x=0 y=0
    transform "normal"
}

